# ==============================================================================# 017_EVENT_ENGINE.py# ==============================================================================import sqlite3import jsonfrom pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS events(    id INTEGER PRIMARY KEY AUTOINCREMENT,    timestamp TEXT,    event TEXT,    origin TEXT,    severity TEXT,    payload TEXT)""")conn.commit()def publish(event, origin, severity="INFO", payload=None):    if payload is None:        payload = {}    cur.execute(        """        INSERT INTO events(            timestamp,            event,            origin,            severity,            payload        )        VALUES(?,?,?,?,?)        """,        (            datetime.now().isoformat(),            event,            origin,            severity,            json.dumps(payload, ensure_ascii=False)        )    )    conn.commit()    return cur.lastrowidpublish(    "MISSION_CONTROL_STARTED",    "017_EVENT_ENGINE",    "INFO",    {        "version":"1.0.0",        "status":"ONLINE"    })cur.execute("""SELECT *FROM eventsORDER BY id DESCLIMIT 10""")print("="*80)print("EVENT ENGINE")print("="*80)for row in cur.fetchall():    print(dict(row))print("="*80)conn.close()

